import base64
import zlib
import gzip
import bz2
import lzma
from google.protobuf.internal.decoder import _DecodeVarint32
import string

b64 = """

""".strip()

data = base64.b64decode(b64)

print("=" * 50)
print("Размер:", len(data))
print("Первые 64 байта HEX:")
print(data[:64].hex())
print("=" * 50)
print(data[:256].hex())
# Попытка protobuf varint
try:
    val, pos = _DecodeVarint32(data, 0)
    print("\n[PROTOBUF VARINT]")
    print("First value:", val)
except Exception as e:
    print("\n[PROTOBUF FAILED]")
    print(e)

# Текстовые кодировки
for enc in ["utf-8", "utf-16", "utf-16le", "utf-16be", "cp1251", "latin-1"]:
    try:
        print(f"\n[{enc}]")
        txt = data.decode(enc)
        print(txt[:1000])
    except Exception:
        pass

# Сжатие
for name, fn in [
    ("zlib", zlib.decompress),
    ("gzip", gzip.decompress),
    ("bz2", bz2.decompress),
    ("lzma", lzma.decompress),
]:
    try:
        print(f"\n[{name.upper()}]")
        out = fn(data)
        print("Размер:", len(out))
        print(out[:500])
    except Exception as e:
        print(f"\n[{name.upper()} FAILED]")
        print(e)

# XOR brute force
print("\n[XOR CHECK]")

results = []

for key in range(256):
    decoded = bytes(b ^ key for b in data)

    score = sum(
        1 for c in decoded
        if 32 <= c <= 126
    )

    results.append((score, key, decoded[:300]))

results.sort(reverse=True)

for score, key, sample in results[:10]:
    print("\n" + "-" * 50)
    print(f"KEY={key} SCORE={score}")

    try:
        print(sample.decode("ascii"))
    except:
        print(repr(sample))

print("\n[ASCII RATIO]")

print(
    sum(
        1 for b in data
        if chr(b) in string.printable
    ) / len(data)
)

print("\n[FREQUENT BYTES]")

from collections import Counter

for byte, count in Counter(data).most_common(20):
    print(hex(byte), count)

tmp = data

for i in range(5):
    try:
        tmp = base64.b64decode(tmp)
        print(f"Layer {i+1}: {len(tmp)} bytes")
        print(tmp[:100])
    except Exception as e:
        print("Stop:", e)
        break